#!/usr/bin/env bash
# Write Buddy.app Version.xcconfig from git tags (same source as Makefile PKG_VERSION).
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"

describe="$(git -C "$root" describe --tags --always --dirty 2>/dev/null || echo dev)"
marketing="$(printf '%s' "$describe" | sed -E 's/^v//;s/-.*//')"
test -n "$marketing" || marketing=0.0.0
year="$(date +%Y)"

xcconfig="$root/macos/Buddy/Version.xcconfig"
mkdir -p "$(dirname "$xcconfig")"
cat >"$xcconfig" <<XCC
// Code generated by scripts/gen-buddy-version.sh; DO NOT EDIT.
MARKETING_VERSION = $marketing
CURRENT_PROJECT_VERSION = 1
COPYRIGHT_YEAR = $year
XCC

echo "gen-buddy-version: describe=$describe marketing=$marketing year=$year"
